const payload = $json.body ?? $json;
const required = ['title', 'propertyType', 'area', 'city', 'countryCode', 'sourceType'];
for (const key of required) {
  if (typeof payload[key] !== 'string' || !payload[key].trim()) throw new Error(`Missing required public listing field: ${key}`);
}
if (Object.hasOwn(payload, 'privateDetails') || Object.hasOwn(payload, 'ownerContact') || Object.hasOwn(payload, 'sellerContact')) {
  throw new Error('Private owner/property contact fields are not accepted');
}
if (!['approved_feed', 'partner_feed', 'public_api'].includes(payload.sourceType)) throw new Error('Source type is not allowed');
const allowed = new Set(['title','summary','description','propertyType','area','city','region','countryCode','price','currency','ownerLedClaim','listingType','bedrooms','bathrooms','posterType','posterEvidence','posterMethod','imageUrls','sourceUrl','externalId','publishedAt','listingUpdatedAt','firstSeenAt','sourceType']);
const clean = Object.fromEntries(Object.entries(payload).filter(([key]) => allowed.has(key)));
return [{ json: clean }];
